using System.IO;
using System.Text.RegularExpressions;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;
using XLua;

public sealed class XluaSmokeTests
{
    [Test]
    public void Lua55BridgeRunsInTheEditor()
    {
        var result = XluaSmoke.Run();
        StringAssert.StartsWith("XLUA_NG_SMOKE_PASS: Lua 5.5", result);
    }

    // require finds a module that exists only in StreamingAssets through the last
    // searcher, LoadFromStreamingAssetsPath. XLUA_NO_STREAMING_ASSETS_LOADER
    // (prepare.py --no-streaming-assets-loader) leaves that searcher out, so the
    // same require fails with Lua's "not found" error.
    [Test]
    public void StreamingAssetsSearcherFollowsTheDefine()
    {
        const string module = "xlua_ng_streaming_assets_probe";
        var dir = Application.streamingAssetsPath;
        var createdDir = !Directory.Exists(dir);
        var file = Path.Combine(dir, module + ".lua");
        Directory.CreateDirectory(dir);
        File.WriteAllText(file, "return 'from StreamingAssets'");
        try
        {
            using (var env = new LuaEnv())
            {
#if !XLUA_NO_STREAMING_ASSETS_LOADER
                LogAssert.Expect(LogType.Warning, new Regex("load lua file from StreamingAssets is obsolete"));
#endif
                var result = env.DoString("return pcall(require, '" + module + "')");
#if XLUA_NO_STREAMING_ASSETS_LOADER
                Assert.AreEqual(false, result[0]);
                StringAssert.Contains("module '" + module + "' not found", (string)result[1]);
                StringAssert.DoesNotContain("streamingAssetsPath", (string)result[1]);
#else
                Assert.AreEqual(true, result[0], result[1] as string);
                Assert.AreEqual("from StreamingAssets", result[1]);
#endif
            }
        }
        finally
        {
            File.Delete(file);
            File.Delete(file + ".meta");
            if (createdDir)
            {
                Directory.Delete(dir, true);
                File.Delete(dir + ".meta");
            }
        }
    }

    // The C# feature defines as the Editor sees them (prepare.py --define NAME). The
    // Editor keeps the template library and perf.profiler with XLUA_NO_TEMPLATE and
    // XLUA_NO_PROFILER; xlua.util and perf.profiler load with no Resources folder
    // (prepare.py copies none); tdr and perf.memory are gone.
    [Test]
    public void FeatureDefinesInTheEditor()
    {
        using (var env = new LuaEnv())
        {
            var result = env.DoString(@"
                local util_ok, util = pcall(require, 'xlua.util')
                local profiler_ok, profiler = pcall(require, 'perf.profiler')
                return type(template), util_ok and type(util.bind) or util,
                    profiler_ok and type(profiler.start) or profiler,
                    (pcall(require, 'tdr')), (pcall(require, 'perf.memory'))");
            Assert.AreEqual("table", result[0]);
#if XLUA_NO_UTIL
            StringAssert.Contains("module 'xlua.util' not found", (string)result[1]);
#else
            Assert.AreEqual("function", result[1]);
#endif
            Assert.AreEqual("function", result[2]);
            Assert.AreEqual(false, result[3]);
            Assert.AreEqual(false, result[4]);
        }
        var signatureLoader = typeof(LuaEnv).Assembly.GetType("XLua.SignatureLoader");
#if XLUA_NO_SIGNATURE_LOADER
        Assert.IsNull(signatureLoader);
#else
        Assert.IsNotNull(signatureLoader);
#endif
        Assert.IsNotNull(typeof(LuaEnv).Assembly.GetType("XLua.TemplateEngine.LuaTemplate"));
    }
}
